/* correlation.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "correlation.h"

/* Tunable blocking factor for the i-dimension in the correlation kernel.
 * Can be overridden at compile time with -DCORR_I_BLOCK=<value>.
 */
#ifndef CORR_I_BLOCK
# define CORR_I_BLOCK 32
#endif


/* Array initialization. */
static
void init_array (int m,
		 int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)N;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = (DATA_TYPE)(i*j)/M + i;

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(corr,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("corr");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, corr[i][j]);
    }
  POLYBENCH_DUMP_END("corr");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_correlation[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k, ii;

  const DATA_TYPE eps = SCALAR_VAL(0.1);

  /* Local restricted views of the arrays to help the compiler with
   * alias analysis and enable more aggressive vectorization.  The
   * PolyBench macros guarantee that these arrays do not alias. */
  DATA_TYPE (*restrict data_)[m]  = (DATA_TYPE (*)[m])data;
  DATA_TYPE (*restrict corr_)[m]  = (DATA_TYPE (*)[m])corr;
  DATA_TYPE *restrict mean_       = mean;
  DATA_TYPE *restrict stddev_     = stddev;

#pragma scop
  /* 1. Compute column means.
   *
   * The original code traversed the matrix column-wise:
   *   for (j) for (i) mean[j] += data[i][j];
   *
   * Here we first zero the means and then traverse the matrix
   * row-major:
   *   for (i) for (j) mean[j] += data[i][j];
   *
   * This uses contiguous accesses to data_[i][j] along j, improving
   * cache locality without changing the mathematical result
   * (only the floating-point accumulation order changes slightly).
   */
  for (j = 0; j < _PB_M; ++j)
    mean_[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; ++i)
    {
      DATA_TYPE *restrict data_row = data_[i];
      for (j = 0; j < _PB_M; ++j)
        mean_[j] += data_row[j];
    }

  for (j = 0; j < _PB_M; ++j)
    mean_[j] /= float_n;


  /* 2. Compute column standard deviations.
   *
   * Again, we use a row-major traversal to improve data cache
   * behavior.  Semantically this computes:
   *   stddev[j] = sqrt( (1/n) * sum_i (data[i][j] - mean[j])^2 ).
   */
  for (j = 0; j < _PB_M; ++j)
    stddev_[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; ++i)
    {
      DATA_TYPE *restrict data_row = data_[i];
      for (j = 0; j < _PB_M; ++j)
        {
          DATA_TYPE diff = data_row[j] - mean_[j];
          stddev_[j] += diff * diff;
        }
    }

  for (j = 0; j < _PB_M; ++j)
    {
      stddev_[j] /= float_n;
      stddev_[j] = SQRT_FUN(stddev_[j]);
      /* Guard against near-zero std. dev. values to avoid division
       * by zero in the normalization step. */
      stddev_[j] = stddev_[j] <= eps ? SCALAR_VAL(1.0) : stddev_[j];
    }


  /* 3. Center and reduce the column vectors.
   *
   * Original code (per element):
   *   data[i][j] -= mean[j];
   *   data[i][j] /= sqrt(float_n) * stddev[j];
   *
   * We algebraically rearrange this to:
   *   data[i][j] = (data[i][j] - mean[j]) *
   *                 (1 / (sqrt(float_n) * stddev[j]));
   *
   * and precompute the per-column scaling factor
   *   stddev_[j] <- 1 / (sqrt(float_n) * stddev_[j]).
   *
   * This replaces a division inside the innermost loop by a
   * multiplication, significantly reducing work while remaining
   * mathematically equivalent up to normal floating-point rounding.
   */
  const DATA_TYPE sqrt_float_n     = SQRT_FUN(float_n);
  const DATA_TYPE inv_sqrt_float_n = SCALAR_VAL(1.0) / sqrt_float_n;

  /* Reuse stddev_ as the array of scaling factors. */
  for (j = 0; j < _PB_M; ++j)
    stddev_[j] = inv_sqrt_float_n / stddev_[j];

  /* Apply centering and scaling in row-major order. */
  for (i = 0; i < _PB_N; ++i)
    {
      DATA_TYPE *restrict data_row = data_[i];
      for (j = 0; j < _PB_M; ++j)
        data_row[j] = (data_row[j] - mean_[j]) * stddev_[j];
    }


  /* 4. Calculate the m * m correlation matrix.
   *
   * Mathematically, with normalized data, corr = data^T * data.
   *
   * The original implementation computed one dot product at a time:
   *   for (i)
   *     for (j > i)
   *       for (k) corr[i][j] += data[k][i] * data[k][j];
   *
   * which accesses the columns of `data` with a large stride in
   * memory.
   *
   * Here we reorganize the computation as a sequence of rank-1
   * updates (outer products) over rows of `data`:
   *
   *   for (k)                  // over rows
   *     for (i)
   *       for (j > i)
   *         corr[i][j] += data[k][i] * data[k][j];
   *
   * This keeps accesses to `data` row-major and makes the inner-most
   * loop over `j` fully contiguous in both `data` and `corr`, which
   * is friendly to caches and vectorization.  The accumulation order
   * changes but the final mathematical result is the same.
   *
   * We only accumulate the upper triangle (i < j) and then copy to
   * the lower triangle by symmetry, while explicitly setting the
   * diagonal to 1.0, as in the original code.
   */

  /* Initialize correlation matrix. We only rely on the upper triangle
   * being non-zero, but zeroing the full matrix is simple and keeps
   * the code clear. */
  for (i = 0; i < _PB_M; ++i)
    for (j = 0; j < _PB_M; ++j)
      corr_[i][j] = SCALAR_VAL(0.0);

  /* Main accumulation: blocked in i for better cache behavior on corr_. */
  for (k = 0; k < _PB_N; ++k)
    {
      DATA_TYPE *restrict data_row = data_[k];

      for (ii = 0; ii < _PB_M; ii += CORR_I_BLOCK)
        {
          int i_end = ii + CORR_I_BLOCK;
          if (i_end > _PB_M)
            i_end = _PB_M;

          for (i = ii; i < i_end; ++i)
            {
              const DATA_TYPE data_ki = data_row[i];
              DATA_TYPE *restrict corr_row_i = corr_[i];

              /* j starts at i+1 since the diagonal is handled separately. */
              for (j = i + 1; j < _PB_M; ++j)
                corr_row_i[j] += data_ki * data_row[j];
            }
        }
    }

  /* Set the diagonal to 1.0 and enforce symmetry. */
  for (i = 0; i < _PB_M; ++i)
    {
      corr_[i][i] = SCALAR_VAL(1.0);
      for (j = i + 1; j < _PB_M; ++j)
        corr_[j][i] = corr_[i][j];
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(corr,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);
  POLYBENCH_1D_ARRAY_DECL(stddev,DATA_TYPE,M,m);

  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_correlation (m, n, float_n,
		      POLYBENCH_ARRAY(data),
		      POLYBENCH_ARRAY(corr),
		      POLYBENCH_ARRAY(mean),
		      POLYBENCH_ARRAY(stddev));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(corr)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(corr);
  POLYBENCH_FREE_ARRAY(mean);
  POLYBENCH_FREE_ARRAY(stddev);

  return 0;
}
