/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations over the baseline PolyBench kernel:
   - Mean and standard deviation are computed using row-major
     traversal to improve cache locality for `data`.
   - Standardization (centering + scaling) is rewritten to use a
     precomputed per-column scale factor, reducing O(N*M) divisions
     to O(M) divisions.
   - The correlation matrix is computed via an outer-product style
     formulation:
         corr = data^T * data
     using the already standardized rows. This greatly improves
     spatial locality for `data` (rows are accessed contiguously),
     at the cost of a different but algebraically equivalent
     accumulation order for floating-point sums.
   - A tunable blocking factor CORR_I_BLOCK is provided for the
     outer-product kernel along the first column index; it can be
     used to tune performance for a specific cache hierarchy while
     preserving semantics. */
static void __attribute__((noinline))
kernel_correlation(int m, int n,
                   DATA_TYPE float_n,
                   DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
                   DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
                   DATA_TYPE POLYBENCH_1D(mean,M,m),
                   DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  const DATA_TYPE eps = SCALAR_VAL(0.1);

  /* Create local restrict-qualified views to help the optimizer.
     Types are VLAs parameterized by the runtime dimension `m`. */
  DATA_TYPE (* __restrict data_)[m]   = data;
  DATA_TYPE (* __restrict corr_)[m]   = corr;
  DATA_TYPE * __restrict mean_        = mean;
  DATA_TYPE * __restrict stddev_      = stddev;

  /* Per-column scaling factor used during standardization:
       scale[j] = 1 / (sqrt(float_n) * stddev[j])
     This allows us to replace a division per element by a single
     division per column plus a multiplication per element. */
  DATA_TYPE scale[_PB_M];
  DATA_TYPE * __restrict scale_ = scale;

#pragma scop

  /* -------------------------------------------------------------
   * 1. Compute column means using row-major traversal.
   *    mean[j] = sum_i data[i][j] / float_n
   * -----------------------------------------------------------*/
  for (j = 0; j < _PB_M; j++)
    mean_[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE * __restrict row = data_[i];
      for (j = 0; j < _PB_M; j++)
        mean_[j] += row[j];
    }

  for (j = 0; j < _PB_M; j++)
    mean_[j] /= float_n;


  /* -------------------------------------------------------------
   * 2. Compute column standard deviations, still in row-major
   *    order.
   *
   *    stddev[j] = sqrt( (1/float_n) * sum_i (data[i][j] - mean[j])^2 )
   *    with a guard against near-zero stddev to avoid division by
   *    zero later.
   * -----------------------------------------------------------*/
  for (j = 0; j < _PB_M; j++)
    stddev_[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE * __restrict row = data_[i];
      for (j = 0; j < _PB_M; j++)
        {
          DATA_TYPE diff = row[j] - mean_[j];
          stddev_[j] += diff * diff;
        }
    }

  for (j = 0; j < _PB_M; j++)
    {
      stddev_[j] /= float_n;
      stddev_[j] = SQRT_FUN(stddev_[j]);
      /* Handle near-zero std. dev. */
      stddev_[j] = stddev_[j] <= eps ? SCALAR_VAL(1.0) : stddev_[j];
    }


  /* -------------------------------------------------------------
   * 3. Center and reduce the column vectors in-place:
   *
   *    data[i][j] <- (data[i][j] - mean[j]) / (sqrt(float_n)*stddev[j])
   *
   *    We precompute a per-column scale factor so that the
   *    innermost loop uses a multiplication instead of a division.
   * -----------------------------------------------------------*/
  DATA_TYPE sqrt_float_n = SQRT_FUN(float_n);

  for (j = 0; j < _PB_M; j++)
    scale_[j] = SCALAR_VAL(1.0) / (sqrt_float_n * stddev_[j]);

  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE * __restrict row = data_[i];
      for (j = 0; j < _PB_M; j++)
        {
          row[j] = (row[j] - mean_[j]) * scale_[j];
        }
    }


  /* -------------------------------------------------------------
   * 4. Compute the m x m correlation matrix.
   *
   *    With standardized data, the correlation between columns i
   *    and j is simply the dot-product over rows:
   *
   *      corr[i][j] = sum_k data[k][i] * data[k][j]
   *
   *    We compute this via an outer-product formulation:
   *
   *      For each row r = data[k][:], do
   *         corr += r^T * r   (on the off-diagonal entries)
   *
   *    This accesses rows of `data` contiguously (good spatial
   *    locality). We only compute the upper triangle (i < j), then
   *    mirror it and set the diagonal entries to 1.0, as in the
   *    original kernel.
   * -----------------------------------------------------------*/

  /* Initialize upper triangle (i < j) to zero. Diagonal is set
     after accumulation, matching original semantics where the
     diagonal is forced to 1.0 exactly. */
  for (i = 0; i < _PB_M; i++)
    for (j = i+1; j < _PB_M; j++)
      corr_[i][j] = SCALAR_VAL(0.0);

  /* Outer-product accumulation.
     The CORR_I_BLOCK parameter allows tuning along the first
     column index `i`, but the default unblocked behavior is also
     preserved (CORR_I_BLOCK simply partitions the i-loop). */
  for (k = 0; k < _PB_N; k++)
    {
      DATA_TYPE * __restrict row = data_[k];

      for (int i0 = 0; i0 < _PB_M; i0 += CORR_I_BLOCK)
        {
          int i_max = i0 + CORR_I_BLOCK;
          if (i_max > _PB_M)
            i_max = _PB_M;

          for (i = i0; i < i_max; i++)
            {
              DATA_TYPE r_i = row[i];
              /* Only j > i: upper triangle, excluding diagonal. */
              for (j = i+1; j < _PB_M; j++)
                corr_[i][j] += r_i * row[j];
            }
        }
    }

  /* Copy the upper triangle to the lower triangle and set the
     diagonal elements to 1.0, exactly as in the original code. */
  for (i = 0; i < _PB_M; i++)
    {
      corr_[i][i] = SCALAR_VAL(1.0);
      for (j = i+1; j < _PB_M; j++)
        corr_[j][i] = corr_[i][j];
    }

#pragma endscop

}


int main(int argc, char** argv)
