  for (j = 0; j < _PB_M; j++)
    {
      stddev_[j] /= float_n;
      stddev_[j] = SQRT_FUN(stddev_[j]);

      /* The following in an inelegant but usual way to handle
         near-zero std. dev. values, which below would cause a zero-
         divide. */
      stddev_[j] = stddev_[j] <= eps ? SCALAR_VAL(1.0) : stddev_[j];
    }


  /* 3. Center and reduce the column vectors.
     Original code:
       for (i)
         for (j)
           data[i][j] -= mean[j];
           data[i][j] /= sqrt(float_n) * stddev[j];

     Here we:
       - Precompute sqrt(float_n) once.
       - For each column j, precompute a single factor
         norm[j] = 1 / (sqrt(float_n) * stddev[j]).
       - Apply: data[i][j] = (data[i][j] - mean[j]) * norm[j].

     This reduces repeated expensive divisions and square roots,
     while computing the same mathematical quantity. */

  DATA_TYPE sqrt_float_n = SQRT_FUN(float_n);

  for (j = 0; j < _PB_M; j++)
    {
      /* One division per column instead of per element. */
      norm[j] = SCALAR_VAL(1.0) / (sqrt_float_n * stddev_[j]);
    }

  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE * __restrict row = data_[i];
      for (j = 0; j < _PB_M; j++)
        {
          /* Center and scale in one fused operation. */
          row[j] = (row[j] - mean_[j]) * norm[j];
        }
    }


  /* 4. Calculate the m * m correlation matrix.

     Original code (upper triangle, then symmetry):
       for (i = 0; i < _PB_M-1; i++)
         {
           corr[i][i] = 1.0;
           for (j = i+1; j < _PB_M; j++)
             {
               corr[i][j] = 0.0;
               for (k = 0; k < _PB_N; k++)
                 corr[i][j] += data[k][i] * data[k][j];
               corr[j][i] = corr[i][j];
             }
         }
       corr[_PB_M-1][_PB_M-1] = 1.0;

     That version repeatedly rescans entire columns for every (i,j)
     pair, which leads to poor cache utilization.

     New scheme:
       - Initialize the upper triangle (i <= j) of corr to 0.
       - For each row k of the normalized data, update all corr[i][j]
         in the upper triangle using data[k][i] * data[k][j].
       - Finally, enforce symmetry and set the diagonal to exactly 1.

     For each fixed (i,j), the accumulation over k still visits k in
     strictly increasing order (0,1,...,_PB_N-1), as in the original
     code, preserving the reduction order in k. */

  /* Initialize upper triangle (including diagonal) to zero. */
  for (i = 0; i < _PB_M; i++)
    for (j = i; j < _PB_M; j++)
      corr_[i][j] = SCALAR_VAL(0.0);

  /* Accumulate dot products row by row. */
  for (k = 0; k < _PB_N; k++)
    {
      DATA_TYPE * __restrict row = data_[k];

      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE row_i = row[i];
          DATA_TYPE * __restrict corr_i = corr_[i];

          /* Only update the upper triangle (j >= i). */
          for (j = i; j < _PB_M; j++)
            {
              corr_i[j] += row_i * row[j];
            }
        }
    }

  /* Enforce exact symmetry and unit diagonal, as in the original. */
  for (i = 0; i < _PB_M; i++)
    {
      corr_[i][i] = SCALAR_VAL(1.0);
      for (j = i+1; j < _PB_M; j++)
        {
          corr_[j][i] = corr_[i][j];
        }
    }
#pragma endscop

}


